def export_members(workspace, recommendation_id):
    from .monitoring_packet import bytes_member, add_member
    from .monitoring_sources import source_export_members
    from .monitoring_workspace import MonitoringWorkspace, csv_text
    record = inspect(workspace, recommendation_id)
    native = designs(workspace, recommendation_id)
    files = {}
    def add(name, body):
        add_member(files, name, bytes_member(body))
    add("recommendation.json", canonical_bytes(record))
    add("selection.json", canonical_bytes(record["selection"]))
    proposal_history = history(workspace, recommendation_id)
    add("proposal-history.json", canonical_bytes(proposal_history))
    evidence_rows = [{"recommendation_id": proposal["id"], "target_id": row["target_id"],
                      "evidence": row["model_evidence"]}
                     for proposal in proposal_history for row in proposal["targets"]
                     if "model_evidence" in row]
    if evidence_rows:
        add("native-evidence.json", canonical_bytes(evidence_rows))
        for name, member in native_evidence.export_members(workspace, proposal_history):
            add_member(files, name, member)
    add("native-designs.json", canonical_bytes(native))
    add("sampling-review.html", report_html(record, native).encode("utf-8"))
    fields = ["target_id", "station_id", "cohort_id", "month", "observed_dates", "minimum_dates", "date_gap", "dates", "observation_ids", "activity_ids"]
    add("historical-month-gaps.csv", csv_text(record["gaps"], fields).encode("utf-8"))
    target_rows = [{**r["target"], "total_cost_cents": r["cost"]["total_cents"],
                    "cohort_fields": r["cohort"]["fields"], "warnings": r["warnings"]} for r in record["targets"]]
    add("proposed-targets.csv", csv_text(target_rows, ["id", "station_id", "cohort_id", "included",
        "months", "minimum_dates_per_month", "proposed_visits", "reporting_limit", "reporting_limit_basis",
        "flow_goal", "priority", "reason", "setup_cost", "per_visit_cost", "total_cost_cents",
        "cost_basis", "sensitivity_basis", "cohort_fields", "warnings",
        *(["model_evidence"] if evidence_rows else [])]).encode("utf-8"))
    for name, member in observed_context.export_members(workspace, record["context_id"]):
        add_member(files, name, member)
    service = MonitoringWorkspace(workspace)
    network = service.get("networks", record["network_id"])
    add("network.json", canonical_bytes(network))
    for label, binding in network["source_bindings"].items():
        if binding:
            for name, member in source_export_members(workspace, "network-" + label, binding):
                add_member(files, name, member)
    for result in native:
        plan = service.get("plans", result["plan_id"])
        if digest(plan) != result["plan_digest"]:
            raise ContractError("The selected native design differs from its retained result")
        add("native-plans/" + plan["id"] + ".json", canonical_bytes(plan))
    add("README.txt", ("Open sampling-review.html for the proposed programme. Historical observations, original sources, complete proposal history, explicit editable selection and all native designs are included.\n"
        "Monthly date targets apply across the chosen historical window. Proposed visits and costs are operator planning inputs. Native calendars do not promise storm occurrence or laboratory suitability.\n"
        "Use the original complete Workspace export/import for editable application receiving. This report bundle retains original scientific files and is not a replacement Workspace.\n").encode("utf-8"))
    add("manifest.json", canonical_bytes({"schema": "upstate.monitoring-recommendation-export/v1",
        "recommendation_id": recommendation_id, "files": [{"path": name, "bytes": member["bytes"], "sha256": member["sha256"]} for name, member in sorted(files.items())]}))
    return files


def export_recommendations(workspace, *, recommendation_id, export_root=None):
    from .monitoring_workspace import MonitoringWorkspace
    from .monitoring_packet import retain_packet
    service = MonitoringWorkspace(workspace, export_root=export_root)
    base = service.export_root or workspace.root.parent / (workspace.root.name + "-monitoring-exports")
    folder = base / ("sampling-proposal-" + uuid.uuid4().hex)
    folder.mkdir(parents=True, exist_ok=False)
    files = export_members(workspace, recommendation_id)
    path = folder / "monitoring-sampling-proposal.zip"
    retain_packet(path, files, metadata="export")
    return service._download(path, {"format": "sampling-proposal", "recommendation_id": recommendation_id,
                                    "files": len(files)})


def verify_workspace(workspace):
    records = [p.stem for p in sorted((workspace.root / COLLECTION).glob("*.json"))]
    for identity in records:
        inspect(workspace, identity)
    saved_designs = [p.stem for p in sorted((workspace.root / DESIGNS).glob("*.json"))]
    for identity in saved_designs:
        inspect_design(workspace, identity)
    return {"recommendations": len(records), "recommendation_designs": len(saved_designs)}


def main():
    from .workspace import Workspace
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True)
    parser.add_argument("action", choices=["catalog", "context", "preview", "prepare", "inspect", "design", "export"])
    parser.add_argument("--request", type=Path)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    request = load_json(args.request) if args.request else {}
    commands = {"catalog": catalog, "context": context, "preview": preview, "prepare": prepare,
                "inspect": inspect, "design": design, "export": export_recommendations}
    result = commands[args.action](Workspace(args.workspace), **request)
    if args.output:
        atomic_json(args.output, result)
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

"""Sampling priorities in the existing operator queue, Workspace and file transport.

TokenJunkieLabs. Observations, original Monitoring designs and field calendars
remain authoritative. This adapter creates no listener or independent queue.
"""
from __future__ import annotations

from copy import deepcopy
import json
from pathlib import Path

from model import monitoring_recommendations as recommendations
from model.common import identifier, verify_file
from model.monitoring_common import atomic_json, digest, file_sha256, held, load_json

PREFIX = "monitoring.recommendations."
ACTIONS = {PREFIX + action for action in ("prepare", "design", "export")}


def _object(value, label):
    if not isinstance(value, dict):
        raise ValueError(label + " must be an object")
    return value


def _payload(task, names):
    value = _object(task.get("payload"), "Sampling request")
    unknown = set(value) - set(names)
    if unknown:
        raise ValueError("Unknown sampling request fields: " + ", ".join(sorted(unknown)))
    return deepcopy(value)


def perform(operator, task):
    action = task.get("action")
    if action not in ACTIONS:
        raise ValueError("Choose a registered sampling-priority action")
    workspace = operator.ws(task["workspace"])
    if action == PREFIX + "prepare":
        values = _payload(task, ("selection", "parent_id", "expected_parent_digest"))
        return recommendations.prepare(
            workspace, operation_id=identifier(task["id"]), **values)
    if action == PREFIX + "design":
        values = _payload(task, ("recommendation_id", "configuration", "title"))
        return recommendations.design(
            workspace, operation_id=identifier(task["id"]), **values)
    return _export_task(operator, workspace, task)


def _export_task(operator, workspace, task):
    """Retain the exact selected edition and reuse the completed export on retry."""
    payload = _payload(task, ("recommendation_id",))
    recommendation_id = identifier(payload.get("recommendation_id"))
    task_id = identifier(task["id"])
    root = operator.root / "outputs" / "monitoring-recommendations" / task_id
    request = {
        "workspace": task["workspace"], "project_id": workspace.project["id"],
        "task_id": task_id, "action": task["action"],
        "payload": {"recommendation_id": recommendation_id},
    }
    request_sha256 = digest(request)
    intent_path, result_path = root / "selection.json", root / "completed.json"
    with held(root / ".export.lock", blocking=False):
        if intent_path.exists():
            previous = load_json(intent_path)
            if previous != {"request": request, "request_sha256": request_sha256}:
                raise ValueError("Sampling export belongs to a different queued selection")
        else:
            atomic_json(intent_path, {"request": request, "request_sha256": request_sha256},
                        immutable=True)
        if result_path.exists():
            completed = load_json(result_path)
            if completed.get("request_sha256") != request_sha256:
                raise ValueError("Saved sampling export belongs to another selection")
            result = completed["result"]
            _export_path(operator, task["id"], result)
            return result
        result = recommendations.export_recommendations(
            workspace, recommendation_id=recommendation_id, export_root=root)
        _export_path(operator, task["id"], result)
        atomic_json(result_path, {"request_sha256": request_sha256, "result": result},
                    immutable=True)
        return result


def _export_path(operator, task_id, result):
    result = _object(result, "Sampling export")
    allowed = (operator.root / "outputs" / "monitoring-recommendations" /
               identifier(task_id)).resolve()
    original = Path(result["path"])
    target = original.resolve(strict=True)
    if original.is_symlink() or not target.is_relative_to(allowed) or not target.is_file():
        raise ValueError("Sampling export must remain in its original task output directory")
    if (target.stat().st_size != result["bytes"]
            or file_sha256(target) != result["sha256"]):
        raise ValueError("The retained sampling export changed")
    return target



def _evidence_downloads(operator, workspace_key, result):
    """Use original file tickets; never save local URLs in scientific identity."""
    public, cache = deepcopy(result), {}
    workspace = operator.ws(workspace_key)
    for row in public.get("targets", []):
        evidence = row.get("model_evidence")
        if evidence is None:
            continue
        source = evidence["source"]
        key = source["collection_id"], source["source_id"]
        if key not in cache:
            links = []
            for item in [source["body"], *source["members"]]:
                name = item.get("view_path", item["filename"])
                target = verify_file(workspace.root, {**item, "path": item["object"]})
                ticket = operator._ticket(workspace_key, target, item,
                                          "Native sampling evidence: " + name)
                links.append({"path": name, "bytes": item["bytes"], "sha256": item["sha256"],
                              "download_url": "/api/file/" + ticket["id"] + "?download=1"})
            cache[key] = links
        evidence["downloads"] = deepcopy(cache[key])
    return public


def read(operator, workspace_key, payload):
    """Read registry query values through the existing authenticated route."""
    payload = _object(payload, "Sampling query")
    values = payload.get("payload", {})
    if isinstance(values, str):
        values = json.loads(values)
    values = _object(values, "Sampling query values")
    action = payload.get("action", "catalog")
    workspace = operator.ws(workspace_key)
    if action == "catalog":
        if values:
            raise ValueError("Sampling catalog takes no selection")
        return {"workspace_key": workspace_key, **recommendations.catalog(workspace)}
    if action == "list":
        if values:
            raise ValueError("Saved sampling list takes no selection")
        return {"workspace_key": workspace_key,
                "recommendations": recommendations.list_saved(workspace)["records"]}
    if action == "preview":
        if set(values) != {"selection"}:
            raise ValueError("Sampling preview needs its complete selection")
        return {"workspace_key": workspace_key,
                **_evidence_downloads(operator, workspace_key,
                    recommendations.preview(workspace, selection=values["selection"]))}
    if action == "context":
        if set(values) != {"context_id"}:
            raise ValueError("Choose one complete saved observational context")
        return {"workspace_key": workspace_key,
                **recommendations.context(workspace, identifier(values["context_id"]))}
    if action == "get":
        if set(values) != {"recommendation_id"}:
            raise ValueError("Choose one complete saved sampling edition")
        return {"workspace_key": workspace_key,
                **_evidence_downloads(operator, workspace_key,
                    recommendations.inspect(workspace, identifier(values["recommendation_id"]))),
                "saved_designs": recommendations.designs(workspace, identifier(values["recommendation_id"]))}
    raise ValueError("Choose catalog, context, list, preview or get for sampling priorities")


def decorate_task(operator, task):
    if task.get("action") not in ACTIONS or task.get("state") != "complete":
        return task
    public = deepcopy(task)
    result = _object(public.get("result"), "Completed sampling result")
    if task["action"] == PREFIX + "export":
        target = _export_path(operator, task["id"], result)
        ticket = operator._ticket(task["workspace"], target, result,
                                  "Sampling priorities and original observations")
        result.pop("path", None)
        result["download_url"] = "/api/file/" + ticket["id"] + "?download=1"
        public["_downloads"] = [ticket]
    else:
        public["_sampling_recommendations"] = {
            "view": "monitoring-recommendations",
            "recommendation_id": result.get("recommendation_id") or result.get("id"),
            "plan_id": result.get("plan_id"),
        }
    return public


def verify_workspace(workspace):
    return recommendations.verify_workspace(workspace)

