  if(!/^\d{4}-\d{2}-\d{2}$/.test(selection.evidence_start||'')||!/^\d{4}-\d{2}-\d{2}$/.test(selection.evidence_end||'')||selection.evidence_end<selection.evidence_start)throw Error('Choose an ordered historical evidence window.');
